fn harness_bin() -> PathBuf {
    PathBuf::from(env!("CARGO_BIN_EXE_harness"))
}

/// Run `harness init` to generate real fixtures
fn init_project(target: &Path, args: &[&str]) -> std::process::Output {
    let mut cmd = Command::new(harness_bin());
    cmd.arg("init").arg(target).args(args);
    cmd.env_clear();
    cmd.env("HOME", target.join("fake-home")); // init needs HOME
    cmd.env("PATH", "/usr/bin:/bin"); // minimal PATH for bash
    cmd.output().expect("run harness init")
}

/// Run `harness doctor` with hermetic environment (no parent env leakage)
fn run_doctor(
    project_dir: &Path,
    home: &Path,
    args: &[&str],
    extra_env: &[(&str, &str)],
) -> std::process::Output {
    let mut cmd = Command::new(harness_bin());
    cmd.arg("doctor");
    cmd.args(args);
    cmd.current_dir(project_dir);

    // Hermetic: clear inherited env, set only what's needed
    cmd.env_clear();
    cmd.env("HOME", home);
    cmd.env("PATH", "/usr/bin:/bin"); // minimal PATH for bash discovery

    for (k, v) in extra_env {
        cmd.env(k, v);
    }

    cmd.output().expect("run harness doctor")
}

/// Parse JSON report from doctor output
fn parse_json_report(stdout: &[u8]) -> Value {
    let text = std::str::from_utf8(stdout).expect("valid UTF-8");
    serde_json::from_str(text).expect("valid JSON")
}

/// Write a minimal valid settings.json with one PreToolUse registration
fn write_settings_with_hook(path: &Path, matcher: &str, command: &str) {
    let settings = serde_json::json!({
        "hooks": {
            "PreToolUse": [
                {
                    "matcher": matcher,
                    "hooks": [
                        {
                            "type": "external",
                            "command": command
                        }
                    ]
                }
            ]
        }
    });

    fs::create_dir_all(path.parent().unwrap()).expect("mkdir .claude");
    fs::write(path, serde_json::to_string_pretty(&settings).unwrap()).expect("write settings.json");
}

/// Write settings with multiple PreToolUse registrations (for duplicate/ambiguous tests)
fn write_settings_with_multiple_hooks(path: &Path, hooks: &[(&str, &str)]) {
    let mut entries = Vec::new();
    for (matcher, command) in hooks {
        entries.push(serde_json::json!({
            "matcher": matcher,
            "hooks": [
                {
                    "type": "external",
                    "command": command
                }
            ]
        }));
    }

    let settings = serde_json::json!({
        "hooks": {
            "PreToolUse": entries
        }
    });

    fs::create_dir_all(path.parent().unwrap()).expect("mkdir .claude");
    fs::write(path, serde_json::to_string_pretty(&settings).unwrap()).expect("write settings.json");
}

/// Write settings with invalid hooks shape (not an array)
fn write_settings_with_invalid_hooks_shape(path: &Path) {
    let settings = serde_json::json!({
        "hooks": {
            "PreToolUse": "not-an-array"
        }
    });

    fs::create_dir_all(path.parent().unwrap()).expect("mkdir .claude");
    fs::write(path, serde_json::to_string_pretty(&settings).unwrap()).expect("write settings.json");
}

/// Write a minimal valid world manifest
fn write_manifest(path: &Path, content: &str) {
    fs::create_dir_all(path.parent().unwrap()).expect("mkdir .claude");
    fs::write(path, content).expect("write manifest");
}

/// Write a trap executable that would create a marker if executed
fn write_trap_executable(path: &Path, marker_path: &Path) {
    let content = format!(
        r#"#!/usr/bin/env bash
touch '{}'
exit 0
"#,
        marker_path.display()
    );

    fs::create_dir_all(path.parent().unwrap()).expect("mkdir trap parent");
    fs::write(path, content).expect("write trap");
    let mut perms = fs::metadata(path).expect("stat trap").permissions();
    perms.set_mode(0o755);
    fs::set_permissions(path, perms).expect("chmod trap");
}

/// Create a fake executable binary (for HARNESS_BIN tests)
fn write_fake_executable(path: &Path) {
    fs::create_dir_all(path.parent().unwrap()).expect("mkdir parent");
    fs::write(path, "#!/bin/sh\necho fake\n").expect("write fake");
    let mut perms = fs::metadata(path).expect("stat").permissions();
    perms.set_mode(0o755);
    fs::set_permissions(path, perms).expect("chmod");
}

/// Capture comprehensive filesystem state
#[derive(Debug, Clone)]
struct FilesystemState {
    entries: HashMap<PathBuf, FileEntry>,
}

#[derive(Debug, Clone, PartialEq)]
enum FileEntry {
    File { content: Vec<u8>, mode: u32 },
    Dir { mode: u32 },
    Symlink { target: PathBuf },
    Missing,
}

impl FilesystemState {
    fn capture(root: &Path) -> Self {
        let mut entries = HashMap::new();
        Self::capture_recursive(root, &mut entries);
        Self { entries }
    }

    fn capture_recursive(path: &Path, entries: &mut HashMap<PathBuf, FileEntry>) {
        let metadata = match fs::symlink_metadata(path) {
            Ok(m) => m,
            Err(_) => {
                entries.insert(path.to_path_buf(), FileEntry::Missing);
                return;
            }
        };

        if metadata.is_symlink() {
            if let Ok(target) = fs::read_link(path) {
                entries.insert(path.to_path_buf(), FileEntry::Symlink { target });
            }
        } else if metadata.is_dir() {
            entries.insert(
                path.to_path_buf(),
                FileEntry::Dir {
                    mode: metadata.permissions().mode(),
                },
            );

            if let Ok(dir_entries) = fs::read_dir(path) {
                for entry in dir_entries.flatten() {
                    Self::capture_recursive(&entry.path(), entries);
                }
            }
        } else if metadata.is_file() {
            let content = fs::read(path).unwrap_or_default();
            entries.insert(
                path.to_path_buf(),
                FileEntry::File {
                    content,
                    mode: metadata.permissions().mode(),
                },
            );
        }
    }

    fn assert_unchanged(&self, root: &Path, label: &str) {
        let after = Self::capture(root);

        for (path, before_entry) in &self.entries {
            let after_entry = after.entries.get(path).unwrap_or(&FileEntry::Missing);
            assert_eq!(
                before_entry,
                after_entry,
                "{label}: file changed: {}",
                path.display()
            );
        }

        for (path, after_entry) in &after.entries {
            if !self.entries.contains_key(path) && !matches!(after_entry, FileEntry::Missing) {
                panic!("{label}: new file created: {}", path.display());
            }
        }
    }
}

