#[test]
fn modern_init_additive_ok() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let project = tmp.path().join("project");
    fs::create_dir_all(&project).expect("mkdir project");

    // Generate real fixtures via harness init
    let out = init_project(&project, &[]);
    assert!(out.status.success(), "init failed");

    let home = tmp.path().join("home");
    fs::create_dir_all(&home).expect("mkdir home");

    let state_before = FilesystemState::capture(&project);

    let out = run_doctor(&project, &home, &["--json"], &[]);

    assert_eq!(out.status.code(), Some(0), "exit must be 0");
    assert_eq!(
        std::str::from_utf8(&out.stderr).unwrap(),
        "",
        "stderr must be empty"
    );

    validate_output_format(&out.stdout, &out.stderr);
    let report = parse_json_report(&out.stdout);
    validate_schema(&report);

    assert_eq!(
        report["summary"]["installation"].as_str(),
        Some("ok"),
        "installation must be ok"
    );
    assert_eq!(report["summary"]["exit_code"].as_i64(), Some(0));

    // Runtime unknown assertion (from test name claim)
    assert_eq!(
        report["summary"]["runtime_enforcement"].as_str(),
        Some("unknown"),
        "runtime must be unknown"
    );

    // ABSENT pass-through finding
    assert!(
        has_finding(&report, "CC_ABSENT_PASSTHROUGH"),
        "must report ABSENT pass-through"
    );

    // Real hash assertion
    assert!(
        report["manifest"]["hash"].is_string(),
        "hash must be present"
    );
    let hash = report["manifest"]["hash"].as_str().unwrap();
    assert_eq!(hash.len(), 64, "hash must be 64 chars");

    state_before.assert_unchanged(&project, "project after doctor");
}

