#[test]
fn narrow_matcher_registration() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let project = tmp.path().join("project");
    let home = tmp.path().join("home");
    fs::create_dir_all(&project).expect("mkdir project");
    fs::create_dir_all(&home).expect("mkdir home");

    // Generate real fixtures
    let out = init_project(&project, &[]);
    assert!(out.status.success());

    // Overwrite settings with narrow matcher
    write_settings_with_hook(
        &project.join(".claude/settings.json"),
        "write_file",
        "bash '.claude/hooks/world-gate.sh'",
    );

    let out = run_doctor(&project, &home, &["--json"], &[]);

    assert_eq!(out.status.code(), Some(1), "partial -> exit 1");
    let report = parse_json_report(&out.stdout);
    assert_eq!(report["summary"]["installation"].as_str(), Some("partial"));
    assert!(has_finding(&report, "CC_PRETOOLUSE_NARROW"));
}

#[test]
fn duplicate_conflicting_managed_registrations() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let project = tmp.path().join("project");
    let home = tmp.path().join("home");
    fs::create_dir_all(&project).expect("mkdir project");
    fs::create_dir_all(&home).expect("mkdir home");

    // Generate real fixtures first
    let out = init_project(&project, &[]);
    assert!(out.status.success());

    // Overwrite with multiple conflicting registrations
    write_settings_with_multiple_hooks(
        &project.join(".claude/settings.json"),
        &[
            ("*", "bash '.claude/hooks/world-gate.sh'"),
            ("*", "bash '.claude/hooks/other-hook.sh'"),
        ],
    );

    let out = run_doctor(&project, &home, &["--json"], &[]);

    assert_eq!(out.status.code(), Some(1), "unknown -> exit 1");
    let report = parse_json_report(&out.stdout);

    // Should preserve all JSON pointers
    let entries = &report["hook"]["entries"];
    assert!(entries.is_array());
    assert_eq!(entries.as_array().unwrap().len(), 2, "both entries kept");

    // Verify JSON pointers are distinct
    let ptr0 = entries[0]["json_pointer"].as_str().unwrap();
    let ptr1 = entries[1]["json_pointer"].as_str().unwrap();
    assert_ne!(ptr0, ptr1, "JSON pointers must be distinct");
    assert!(has_finding(&report, "CC_PRETOOLUSE_AMBIGUOUS"));
}

#[test]
fn fake_echo_mentioning_worldgate_never_recognized() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let project = tmp.path().join("project");
    let home = tmp.path().join("home");
    fs::create_dir_all(&project).expect("mkdir project");
    fs::create_dir_all(&home).expect("mkdir home");

    write_settings_with_hook(
        &project.join(".claude/settings.json"),
        "*",
        "echo 'world-gate.sh was here'",
    );

    let out = run_doctor(&project, &home, &["--json"], &[]);

    // Tighten assertion per review: check exit and status, not just shim_profile
    assert_eq!(out.status.code(), Some(2), "fake echo -> broken");

    let report = parse_json_report(&out.stdout);
    assert_eq!(
        report["summary"]["installation"].as_str(),
        Some("broken"),
        "fake echo -> broken status"
    );
    assert!(
        report["hook"]["shim_profile"].is_null(),
        "fake echo must not be recognized"
    );
    assert!(has_finding(&report, "CC_SHIM_UNSUPPORTED"));
}

#[test]
fn fake_shim_with_markers_only_in_comments() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let project = tmp.path().join("project");
    let home = tmp.path().join("home");
    fs::create_dir_all(&project).expect("mkdir project");
    fs::create_dir_all(&home).expect("mkdir home");

    // Write fake shim with marker strings only in comments (should NOT be recognized)
    let fake_shim = project.join(".claude/hooks/world-gate.sh");
    fs::create_dir_all(fake_shim.parent().unwrap()).expect("mkdir hooks");
    fs::write(
        &fake_shim,
        r#"#!/usr/bin/env bash
# This is a fake script
# It mentions: ai2rules governance shim
# and cc-hook
# and TRUSTED_BIN
# But they're all in comments!
echo "fake"
"#,
    )
    .expect("write fake shim");

    write_settings_with_hook(
        &project.join(".claude/settings.json"),
        "*",
        "bash '.claude/hooks/world-gate.sh'",
    );
    write_manifest(&project.join(".claude/cc-world.yaml"), "world_id: test\n");

    let out = run_doctor(&project, &home, &["--json"], &[]);

    let report = parse_json_report(&out.stdout);
    assert!(
        report["hook"]["shim_profile"].is_null() || report["hook"]["shim_profile"] == "unsupported",
        "markers in comments only must not be recognized"
    );
}

