    let out1 = run_doctor(&project, &home, &["--json"], &[]);
    assert_eq!(out1.status.code(), Some(0), "first run -> ok/0");
    let report1 = parse_json_report(&out1.stdout);
    let hash1 = report1["manifest"]["hash"].as_str().unwrap();

    // Read current manifest
    let original = fs::read_to_string(project.join(".claude/cc-world.yaml")).unwrap();

