#[test]
fn human_and_json_mode_consistency() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let project = tmp.path().join("project");
    let home = tmp.path().join("home");
    fs::create_dir_all(&project).expect("mkdir project");
    fs::create_dir_all(&home).expect("mkdir home");

    let out = init_project(&project, &[]);
    assert!(out.status.success());

    let human_out1 = run_doctor(&project, &home, &[], &[]);
    let human_out2 = run_doctor(&project, &home, &[], &[]);
    let json_out1 = run_doctor(&project, &home, &["--json"], &[]);
    let json_out2 = run_doctor(&project, &home, &["--json"], &[]);

    // Both must exit with same code
    assert_eq!(human_out1.status.code(), json_out1.status.code());

    // Human mode: deterministic stdout, empty stderr
    assert_eq!(
        human_out1.stdout, human_out2.stdout,
        "human mode must be deterministic"
    );
    assert!(
        human_out1.stderr.is_empty(),
        "human mode stderr must be empty"
    );

    // JSON mode: deterministic stdout
    assert_eq!(
        json_out1.stdout, json_out2.stdout,
        "JSON mode must be deterministic"
    );

    // Human output must contain semantic phrases
    let human_text = String::from_utf8_lossy(&human_out1.stdout);
    assert!(human_text.contains("Installation:"));
    assert!(human_text.contains("Schema:"));
    assert!(!human_text.contains("protected"));

    // JSON output must be valid
    let report = parse_json_report(&json_out1.stdout);
    validate_schema(&report);
}

#[test]
fn clap_parse_error_exit_2_vs_diagnostic_exit_2() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let project = tmp.path().join("project");
    let home = tmp.path().join("home");
    fs::create_dir_all(&project).expect("mkdir project");
    fs::create_dir_all(&home).expect("mkdir home");

    // Clap parse error (unknown flag)
    let mut cmd = Command::new(harness_bin());
    cmd.arg("doctor");
    cmd.arg("--invalid-flag");
    cmd.current_dir(&project);
    cmd.env_clear();
    cmd.env("HOME", &home);
    let clap_out = cmd.output().expect("run with invalid flag");

    assert_eq!(clap_out.status.code(), Some(2), "clap must exit 2");
    assert!(!clap_out.stderr.is_empty(), "clap error must write stderr");

    // Diagnostic exit 2
    write_settings_with_hook(
        &project.join(".claude/settings.json"),
        "*",
        "bash '.claude/hooks/world-gate.sh'",
    );

    let diag_out = run_doctor(&project, &home, &["--json"], &[]);

    assert_eq!(diag_out.status.code(), Some(2), "diagnostic must exit 2");
    assert!(
        diag_out.stderr.is_empty(),
        "diagnostic stderr must be empty"
    );
    let report = parse_json_report(&diag_out.stdout);
    assert_eq!(report["summary"]["installation"].as_str(), Some("broken"));
}

