#[test]
fn symlink_loop_in_binary_path() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let project = tmp.path().join("project");
    let home = tmp.path().join("home");
    fs::create_dir_all(&project).expect("mkdir project");
    fs::create_dir_all(&home).expect("mkdir home");

    let out = init_project(&project, &[]);
    assert!(out.status.success());

    let bin_a = tmp.path().join("harness-a");
    let bin_b = tmp.path().join("harness-b");

    std::os::unix::fs::symlink(&bin_b, &bin_a).expect("symlink a->b");
    std::os::unix::fs::symlink(&bin_a, &bin_b).expect("symlink b->a");

    let out = run_doctor(
        &project,
        &home,
        &["--json"],
        &[("HARNESS_BIN", bin_a.to_str().unwrap())],
    );

    assert_eq!(out.status.code(), Some(2), "symlink loop -> broken/2");
    let report = parse_json_report(&out.stdout);
    assert_eq!(report["summary"]["installation"].as_str(), Some("broken"));
}

#[test]
fn dangling_symlink_in_binary_path() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let project = tmp.path().join("project");
    let home = tmp.path().join("home");
    fs::create_dir_all(&project).expect("mkdir project");
    fs::create_dir_all(&home).expect("mkdir home");

    let out = init_project(&project, &[]);
    assert!(out.status.success());

    let bin_link = tmp.path().join("harness-link");
    let target = tmp.path().join("nonexistent-target");

    std::os::unix::fs::symlink(&target, &bin_link).expect("dangling symlink");

    let out = run_doctor(
        &project,
        &home,
        &["--json"],
        &[("HARNESS_BIN", bin_link.to_str().unwrap())],
    );

    assert_eq!(out.status.code(), Some(2), "dangling symlink -> broken/2");
    let report = parse_json_report(&out.stdout);
    assert_eq!(report["summary"]["installation"].as_str(), Some("broken"));
    assert_eq!(
        report["binaries"]["hook_harness"]["status"].as_str(),
        Some("missing")
    );
}

#[test]
fn paths_with_spaces_quotes_metacharacters() {
    let tmp = tempfile::tempdir().expect("tempdir");
    // Test with spaces, quotes, and shell metacharacters in path
    let project = tmp.path().join("project with 'quotes' and $var");
    let home = tmp.path().join("home");
    fs::create_dir_all(&project).expect("mkdir project");
    fs::create_dir_all(&home).expect("mkdir home");

    let out = init_project(&project, &[]);
    assert!(out.status.success());

    let out = run_doctor(&project, &home, &["--json"], &[]);

    // Should handle special chars correctly without crashing
    let report = parse_json_report(&out.stdout);
    validate_schema(&report);

    // Project path should contain the special characters
    let project_path = report["project"]["path"].as_str().unwrap();
    assert!(project_path.contains("quotes"), "path must preserve quotes");
    assert!(
        project_path.contains("$var") || project_path.contains("var"),
        "path must preserve metacharacters"
    );
}
